mapper.select:
select h.calc_hist_id as "calcHistId", h.target_user_id as "targetUserId", case when k.name is not null then k.name else u.login_id end as "targetUserName", h.evaluation_year as "evaluationYear", h.area_code as "areaCode", h.area_name as "areaName", h.source_achievement_id as "sourceAchievementId", h.source_achievement_title as "sourceAchievementTitle", h.management_item_code as "managementItemCode", h.base_score as "baseScore", h.participation_type as "participationType", h.distribution_rate as "distributionRate", h.cap_applied_yn as "capAppliedYn", h.formula_version_id as "formulaVersionId", h.generation_no as "generationNo", h.calculated_score as "calculatedScore", h.calculation_steps_json::text as "calculationStepsJson", h.source_achievement_link as "sourceAchievementLink", h.request_id as "requestId", h.calculated_at as "calculatedAt", '점수·기준점수·배분율·계산식 수정 없이 조회만 제공하는 산출근거입니다.' as "readOnlyNotice" from biz_score_calc_hist h join users u on u.user_id = h.target_user_id left join korus_personnel_snapshots k on k.employee_no = u.employee_no where h.calc_hist_id = #{calcHistId}
and h.target_user_id = #{selfUserId}
and h.organization_code = #{organizationCode}
limit 1
